import type { AssignmentStatusHistorySource } from '~/client';

interface AssignmentStatusHistorySourceEntry {
  label: string;
  systemInitiated: boolean;
  description: string;
}

export const assignmentStatusHistorySourceConfig: Record<
  AssignmentStatusHistorySource,
  AssignmentStatusHistorySourceEntry
> = {
  manual_update: {
    label: 'Manual update',
    systemInitiated: false,
    description: 'An admin or manager changed the status',
  },
  project_completed: {
    label: 'Project completed',
    systemInitiated: false,
    description: 'Project moved to completed/removed',
  },
  assigned: { label: 'Assigned', systemInitiated: false, description: 'Initial assignment' },
  application_approved: {
    label: 'Application approved',
    systemInitiated: false,
    description: 'Canvasser application approved',
  },
  auto_active_to_inactive: {
    label: 'Auto: inactive',
    systemInitiated: true,
    description: 'Scheduled job marked canvasser inactive due to lack of activity',
  },
  auto_trained_to_inactive: {
    label: 'Auto: inactive',
    systemInitiated: true,
    description: 'Scheduled job marked trained canvasser inactive due to lack of activity',
  },
  auto_inactive_to_active: {
    label: 'Auto: active',
    systemInitiated: true,
    description: 'Scheduled job marked canvasser active — activity detected',
  },
  legacy_backfill: {
    label: 'Initial record',
    systemInitiated: true,
    description: 'Imported when history tracking was introduced',
  },
};

const defaultAssignmentStatusHistorySource: AssignmentStatusHistorySourceEntry = {
  label: '',
  systemInitiated: false,
  description: '',
};

export function getAssignmentStatusHistorySource(
  source: AssignmentStatusHistorySource
): AssignmentStatusHistorySourceEntry {
  return (
    assignmentStatusHistorySourceConfig[source] ?? {
      ...defaultAssignmentStatusHistorySource,
      label: snakeCaseToCapitalizedCase(source),
      description: snakeCaseToCapitalizedCase(source),
    }
  );
}
