<template>
  <Card>
    <CardHeader>
      <CardTitle>Status History</CardTitle>
    </CardHeader>
    <CardContent class="p-0 md:p-0">
      <AppLoader v-if="isLoading" variant="inline" subject="status history" />
      <AppError
        v-else-if="error"
        title="Failed to load status history"
        :error="error"
        variant="table"
        :action="refetch"
        action-text="Retry"
      />
      <AppEmpty v-else-if="items.length === 0" subject="status changes" variant="table" />
      <ol v-else class="flex flex-col p-4 md:p-6">
        <li v-for="(item, idx) in items" :key="item.id" class="flex gap-3">
          <div class="flex flex-col items-center">
            <div class="size-3 rounded-full bg-muted-foreground mt-1.5 shrink-0" />
            <div v-if="idx < items.length - 1" class="w-px flex-1 bg-border" />
          </div>
          <div class="flex-1 flex flex-col gap-1" :class="idx < items.length - 1 ? 'pb-6' : ''">
            <div class="flex flex-wrap items-center gap-2">
              <Badge v-if="item.from_status" :variant="getAssignmentStatus(item.from_status).variant" size="sm">
                {{ getAssignmentStatus(item.from_status).name }}
              </Badge>
              <Badge v-else size="sm" variant="default">Initial</Badge>
              <ArrowRightIcon class="h-4 w-4 text-muted-foreground" />
              <Badge :variant="getAssignmentStatus(item.to_status).variant" size="sm">
                {{ getAssignmentStatus(item.to_status).name }}
              </Badge>
            </div>
            <p class="text-sm text-muted-foreground">
              {{ formatDateTzToFormat(new Date(item.changed_at), 'MM/dd/yyyy, hh:mm aaa', timezone) }}
            </p>
            <div class="text-sm flex flex-wrap items-center gap-2">
              <template v-if="item.changed_by_user_id">
                <span>by</span>
                <InlineEntityUser :user-id="item.changed_by_user_id" />
              </template>
              <span v-else class="italic text-muted-foreground">
                System — {{ getAssignmentStatusHistorySource(item.source).description }}
              </span>
            </div>
            <p v-if="item.reason" class="text-xs text-muted-foreground">{{ item.reason }}</p>
          </div>
        </li>
      </ol>
      <div v-if="totalCount > 0" class="p-4 md:p-6 border-t">
        <AppPagination :page="page" :size="size" :total="totalCount" label="changes" />
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { ArrowRightIcon } from 'lucide-vue-next';
import { getAssignmentStatusHistory, type AssignmentStatusHistoryListItem } from '~/client';
import { getAssignmentStatus } from '~/constants/assignments/assignmentStatusConfig';
import { getAssignmentStatusHistorySource } from '~/constants/assignments/assignmentStatusHistorySourceConfig';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

const props = defineProps<{
  projectId: string;
  userId: string;
}>();

const { timezone } = useUserRole();

const route = useRoute();
const page = computed(() => Number(route.query.page) || 1);
const size = computed(() => Number(route.query.size) || 20);

const {
  data: history,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['assignment.status-history', props.projectId, props.userId, page.value, size.value],
  query: () =>
    getAssignmentStatusHistory({
      composable: '$fetch',
      path: { project_id: props.projectId, user_id: props.userId },
      query: { page: page.value, size: size.value },
    }),
  enabled: () => !!props.projectId && !!props.userId,
});

const items = computed<AssignmentStatusHistoryListItem[]>(() => history.value?.items ?? []);
const totalCount = computed(() => history.value?.total_count ?? 0);
</script>
